/**
 * Preprocessing pipeline — Phase 2
 *
 * Runs an ordered list of modular preprocessors and records per-step timing.
 */

import type {
  BrightnessOptions,
  ContrastOptions,
  DenoiseOptions,
  FrameBuffer,
  PipelineMetrics,
  PreprocessorId,
  PreprocessStepResult,
  ResizeOptions,
  ROI,
  SharpenOptions,
  ThresholdOptions,
} from './types';
import {
  brightness,
  contrast,
  crop,
  denoise,
  grayscale,
  resize,
  sharpen,
  threshold,
} from './preprocessors';

export interface PipelineStepConfig {
  id: PreprocessorId;
  enabled: boolean;
  options?: Record<string, unknown>;
}

export const DEFAULT_PIPELINE: PipelineStepConfig[] = [
  { id: 'grayscale', enabled: true },
  { id: 'contrast', enabled: false, options: { factor: 1.4 } },
  { id: 'brightness', enabled: false, options: { amount: 15 } },
  { id: 'denoise', enabled: false, options: { radius: 1 } },
  { id: 'sharpen', enabled: false, options: { amount: 0.5 } },
  { id: 'threshold', enabled: false, options: { value: 128 } },
  { id: 'resize', enabled: false, options: { width: 640, height: 480 } },
];

export class ProcessingPipeline {
  private steps: PipelineStepConfig[];

  constructor(steps: PipelineStepConfig[] = DEFAULT_PIPELINE.map((s) => ({ ...s }))) {
    this.steps = steps;
  }

  getConfigs(): PipelineStepConfig[] {
    return this.steps.map((s) => ({ ...s, options: s.options ? { ...s.options } : undefined }));
  }

  setEnabled(id: PreprocessorId, enabled: boolean): void {
    const step = this.steps.find((s) => s.id === id);
    if (step) step.enabled = enabled;
  }

  setOptions(id: PreprocessorId, options: Record<string, unknown>): void {
    const step = this.steps.find((s) => s.id === id);
    if (step) step.options = { ...step.options, ...options };
  }

  /**
   * Run the enabled steps in order.
   * Optional ROI is applied first (crop on the source buffer).
   */
  run(input: FrameBuffer, roi?: ROI): { frame: FrameBuffer; metrics: PipelineMetrics } {
    const stepsTiming: PreprocessStepResult[] = [];
    const t0 = performance.now();
    let current = input;

    if (roi) {
      const t = performance.now();
      current = crop(current, roi);
      stepsTiming.push({ name: 'roi', durationMs: performance.now() - t });
    }

    for (const step of this.steps) {
      if (!step.enabled) continue;
      const t = performance.now();
      current = this.applyStep(current, step);
      stepsTiming.push({ name: step.id, durationMs: performance.now() - t });
    }

    const processMs = performance.now() - t0;
    return {
      frame: current,
      metrics: {
        captureMs: 0,
        processMs,
        totalMs: processMs,
        steps: stepsTiming,
        width: current.width,
        height: current.height,
        format: current.format,
      },
    };
  }

  private applyStep(frame: FrameBuffer, step: PipelineStepConfig): FrameBuffer {
    switch (step.id) {
      case 'grayscale':
        return grayscale(frame);
      case 'contrast':
        return contrast(frame, step.options as unknown as ContrastOptions);
      case 'brightness':
        return brightness(frame, step.options as unknown as BrightnessOptions);
      case 'sharpen':
        return sharpen(frame, step.options as unknown as SharpenOptions);
      case 'threshold':
        return threshold(frame, step.options as unknown as ThresholdOptions);
      case 'denoise':
        return denoise(frame, step.options as unknown as DenoiseOptions);
      case 'resize':
        return resize(frame, step.options as unknown as ResizeOptions);
      case 'roi':
        return frame;
      default:
        return frame;
    }
  }
}
