/**
 * BarcodeDecoder — Phase 3
 *
 * Single-barcode detection using zxing-wasm (ZXing-C++ WASM).
 * Input: FrameBuffer from the processing pipeline (RGBA preferred).
 */

import type { BarcodeFormat, BarcodeResult, BoundingBox } from '../types';
import type { FrameBuffer } from '../processing/types';
import { logger } from '../utils/logger';

/** Subset of zxing format strings we map into our BarcodeFormat */
type ZXingFormat =
  | 'Aztec'
  | 'Codabar'
  | 'Code39'
  | 'Code93'
  | 'Code128'
  | 'DataBar'
  | 'DataBarExpanded'
  | 'DataMatrix'
  | 'EAN-8'
  | 'EAN-13'
  | 'ITF'
  | 'MaxiCode'
  | 'PDF417'
  | 'QRCode'
  | 'MicroQRCode'
  | 'UPC-A'
  | 'UPC-E'
  | string;

interface ZXingReadResult {
  text: string;
  format: ZXingFormat;
  symbology?: string;
  position?: {
    topLeft?: { x: number; y: number };
    topRight?: { x: number; y: number };
    bottomLeft?: { x: number; y: number };
    bottomRight?: { x: number; y: number };
  };
  orientation?: number;
}

type ReadBarcodesFn = (
  input: ImageData | Blob | ArrayBuffer | Uint8Array,
  options?: Record<string, unknown>
) => Promise<ZXingReadResult[]>;

export interface DecoderOptions {
  /** Limit symbols — Phase 3 keeps this at 1 */
  maxNumberOfSymbols?: number;
  tryHarder?: boolean;
  /** Empty = try all supported formats */
  formats?: string[];
}

const DEFAULT_OPTIONS: Required<DecoderOptions> = {
  maxNumberOfSymbols: 1,
  tryHarder: true,
  formats: [],
};

export class BarcodeDecoder {
  private readBarcodes: ReadBarcodesFn | null = null;
  private initPromise: Promise<void> | null = null;
  private ready = false;

  get isReady(): boolean {
    return this.ready;
  }

  /**
   * Lazy-load zxing-wasm reader. Safe to call multiple times.
   */
  async init(): Promise<void> {
    if (this.ready && this.readBarcodes) return;
    if (this.initPromise) return this.initPromise;

    this.initPromise = (async () => {
      try {
        // Prefer reader subpath (smaller WASM). Fall back to package root.
        let mod: { readBarcodes?: ReadBarcodesFn };
        try {
          mod = await import('zxing-wasm/reader');
        } catch {
          mod = await import('zxing-wasm');
        }
        if (typeof mod.readBarcodes !== 'function') {
          throw new Error('zxing-wasm did not export readBarcodes');
        }
        this.readBarcodes = mod.readBarcodes;
        this.ready = true;
        logger.info('BarcodeDecoder initialized (zxing-wasm)');
      } catch (e) {
        this.initPromise = null;
        logger.error('BarcodeDecoder init failed', e);
        throw e;
      }
    })();

    return this.initPromise;
  }

  /**
   * Decode a single barcode from a FrameBuffer.
   * Returns null when nothing is found.
   */
  async decode(
    frame: FrameBuffer,
    options: DecoderOptions = {}
  ): Promise<BarcodeResult | null> {
    await this.init();
    if (!this.readBarcodes) return null;

    const opts = { ...DEFAULT_OPTIONS, ...options };
    const imageData = frameToImageData(frame);

    const readerOptions: Record<string, unknown> = {
      tryHarder: opts.tryHarder,
      maxNumberOfSymbols: opts.maxNumberOfSymbols,
    };
    if (opts.formats.length > 0) {
      readerOptions.formats = opts.formats;
    }

    const t0 = performance.now();
    let results: ZXingReadResult[];
    try {
      results = await this.readBarcodes(imageData, readerOptions);
    } catch (e) {
      logger.warn('decode call failed', e);
      return null;
    }
    const decodeMs = performance.now() - t0;

    if (!results || results.length === 0) {
      return null;
    }

    // Phase 3: single barcode — take first result
    const hit = results[0]!;
    const mapped = mapResult(hit);
    logger.debug('Barcode decoded', {
      value: mapped.value,
      format: mapped.format,
      decodeMs: decodeMs.toFixed(1),
    });
    return mapped;
  }
}

function frameToImageData(frame: FrameBuffer): ImageData {
  if (frame.format === 'rgba') {
    // ImageData requires a fresh Uint8ClampedArray owned buffer in some engines
    const copy = new Uint8ClampedArray(frame.data);
    return new ImageData(copy, frame.width, frame.height);
  }

  // Expand gray → RGBA
  const rgba = new Uint8ClampedArray(frame.width * frame.height * 4);
  for (let i = 0, j = 0; i < frame.data.length; i++, j += 4) {
    const v = frame.data[i]!;
    rgba[j] = v;
    rgba[j + 1] = v;
    rgba[j + 2] = v;
    rgba[j + 3] = 255;
  }
  return new ImageData(rgba, frame.width, frame.height);
}

function mapResult(hit: ZXingReadResult): BarcodeResult {
  const bounds = positionToBounds(hit.position);
  return {
    value: hit.text ?? '',
    format: mapFormat(hit.format),
    bounds,
    timestamp: Date.now(),
  };
}

function mapFormat(format: ZXingFormat): BarcodeFormat {
  const f = String(format).toLowerCase().replace(/[_-\s]/g, '');
  switch (f) {
    case 'ean8':
      return 'EAN_8';
    case 'ean13':
      return 'EAN_13';
    case 'upca':
      return 'UPC_A';
    case 'upce':
      return 'UPC_E';
    case 'code39':
      return 'CODE_39';
    case 'code93':
      return 'CODE_93';
    case 'code128':
      return 'CODE_128';
    case 'itf':
    case 'interleaved2of5':
      return 'ITF';
    case 'codabar':
      return 'CODABAR';
    case 'databar':
    case 'rss14':
      return 'RSS_14';
    case 'databarexpanded':
    case 'rssexpanded':
      return 'RSS_EXPANDED';
    case 'qrcode':
      return 'QR_CODE';
    case 'microqrcode':
      return 'MICRO_QR';
    case 'datamatrix':
      return 'DATA_MATRIX';
    case 'aztec':
      return 'AZTEC';
    case 'pdf417':
      return 'PDF_417';
    default:
      return 'UNKNOWN';
  }
}

function positionToBounds(
  position?: ZXingReadResult['position']
): BoundingBox {
  if (!position) {
    return { x: 0, y: 0, width: 0, height: 0 };
  }
  const points = [
    position.topLeft,
    position.topRight,
    position.bottomLeft,
    position.bottomRight,
  ].filter(Boolean) as Array<{ x: number; y: number }>;

  if (points.length === 0) {
    return { x: 0, y: 0, width: 0, height: 0 };
  }

  const xs = points.map((p) => p.x);
  const ys = points.map((p) => p.y);
  const minX = Math.min(...xs);
  const maxX = Math.max(...xs);
  const minY = Math.min(...ys);
  const maxY = Math.max(...ys);

  return {
    x: minX,
    y: minY,
    width: maxX - minX,
    height: maxY - minY,
    corners: points,
  };
}
