/**
 * FrameCapture — grab frames from an HTMLVideoElement
 *
 * Uses Canvas 2D (widely supported). OffscreenCanvas is used when available
 * for the processing path, but capture from <video> still goes through a
 * visible/hidden canvas for maximum Samsung Internet compatibility.
 */

import type { FrameBuffer, ROI } from './types';
import { logger } from '../utils/logger';

export interface CaptureOptions {
  /** Optional downscale max width (keeps aspect ratio). */
  maxWidth?: number;
  /** Optional ROI in video pixel coordinates. */
  roi?: ROI;
}

export class FrameCapture {
  private canvas: HTMLCanvasElement;
  private ctx: CanvasRenderingContext2D;
  private offscreen: OffscreenCanvas | null = null;
  private offscreenCtx: OffscreenCanvasRenderingContext2D | null = null;

  constructor() {
    this.canvas = document.createElement('canvas');
    const ctx = this.canvas.getContext('2d', {
      willReadFrequently: true,
      alpha: false,
    });
    if (!ctx) {
      throw new Error('Canvas 2D context not available');
    }
    this.ctx = ctx;

    if (typeof OffscreenCanvas !== 'undefined') {
      try {
        this.offscreen = new OffscreenCanvas(1, 1);
        this.offscreenCtx = this.offscreen.getContext('2d', {
          willReadFrequently: true,
          alpha: false,
        }) as OffscreenCanvasRenderingContext2D | null;
      } catch {
        this.offscreen = null;
        this.offscreenCtx = null;
      }
    }
  }

  /** Whether OffscreenCanvas is usable in this environment */
  get supportsOffscreen(): boolean {
    return this.offscreenCtx != null;
  }

  /**
   * Capture one frame from a playing video element into a FrameBuffer (RGBA).
   */
  captureFromVideo(video: HTMLVideoElement, options: CaptureOptions = {}): FrameBuffer {
    const vw = video.videoWidth;
    const vh = video.videoHeight;
    if (!vw || !vh) {
      throw new Error('Video has no dimensions yet (videoWidth/videoHeight is 0)');
    }

    let sx = 0;
    let sy = 0;
    let sw = vw;
    let sh = vh;

    if (options.roi) {
      sx = Math.max(0, Math.floor(options.roi.x));
      sy = Math.max(0, Math.floor(options.roi.y));
      sw = Math.min(vw - sx, Math.floor(options.roi.width));
      sh = Math.min(vh - sy, Math.floor(options.roi.height));
      if (sw <= 0 || sh <= 0) {
        throw new Error('ROI is empty or outside the video frame');
      }
    }

    let dw = sw;
    let dh = sh;
    if (options.maxWidth && sw > options.maxWidth) {
      const scale = options.maxWidth / sw;
      dw = Math.max(1, Math.round(sw * scale));
      dh = Math.max(1, Math.round(sh * scale));
    }

    const t0 = performance.now();

    // Prefer OffscreenCanvas when available; fall back to HTMLCanvasElement
    if (this.offscreen && this.offscreenCtx) {
      this.offscreen.width = dw;
      this.offscreen.height = dh;
      this.offscreenCtx.drawImage(video, sx, sy, sw, sh, 0, 0, dw, dh);
      const imageData = this.offscreenCtx.getImageData(0, 0, dw, dh);
      const elapsed = performance.now() - t0;
      logger.debug('Frame captured (OffscreenCanvas)', { dw, dh, elapsed });
      return {
        width: dw,
        height: dh,
        format: 'rgba',
        data: imageData.data,
        timestamp: performance.now(),
      };
    }

    this.canvas.width = dw;
    this.canvas.height = dh;
    this.ctx.drawImage(video, sx, sy, sw, sh, 0, 0, dw, dh);
    const imageData = this.ctx.getImageData(0, 0, dw, dh);
    const elapsed = performance.now() - t0;
    logger.debug('Frame captured (HTMLCanvas)', { dw, dh, elapsed });

    return {
      width: dw,
      height: dh,
      format: 'rgba',
      data: imageData.data,
      timestamp: performance.now(),
    };
  }

  /**
   * Draw a FrameBuffer onto a target canvas (for UI preview).
   */
  drawToCanvas(frame: FrameBuffer, target: HTMLCanvasElement): void {
    if (target.width !== frame.width) target.width = frame.width;
    if (target.height !== frame.height) target.height = frame.height;

    const ctx = target.getContext('2d');
    if (!ctx) return;

    if (frame.format === 'rgba') {
      const imageData = new ImageData(frame.data, frame.width, frame.height);
      ctx.putImageData(imageData, 0, 0);
      return;
    }

    // gray → expand to RGBA for display
    const rgba = new Uint8ClampedArray(frame.width * frame.height * 4);
    const src = frame.data;
    for (let i = 0, j = 0; i < src.length; i++, j += 4) {
      const v = src[i]!;
      rgba[j] = v;
      rgba[j + 1] = v;
      rgba[j + 2] = v;
      rgba[j + 3] = 255;
    }
    ctx.putImageData(new ImageData(rgba, frame.width, frame.height), 0, 0);
  }
}
