/**
 * Phase 2 UI — Camera + Frame Processing demo
 */

import { CameraEngine } from '../camera';
import type { CameraError, CameraState } from '../types';
import { CURRENT_PHASE, PROJECT_VERSION } from '../types';
import {
  FrameCapture,
  ProcessingPipeline,
  runPipelineBenchmark,
  type BenchmarkResult,
  type PreprocessorId,
} from '../processing';
import { BarcodeDecoder } from '../decoder';
import type { BarcodeResult } from '../types';
import { logger } from '../utils/logger';

export function renderApp(root: HTMLElement): void {
  const engine = new CameraEngine();
  const capture = new FrameCapture();
  const pipeline = new ProcessingPipeline();
  const decoder = new BarcodeDecoder();
  let decodeBusy = false;
  let highlightUntil = 0;
  let highlightResult: BarcodeResult | null = null;
  let lastProcessSize = { width: 0, height: 0 };
  let audioCtx: AudioContext | null = null;

  let processLoopId: number | null = null;
  let fpsWindow: number[] = [];

  root.innerHTML = `
    <div class="app-shell">
      <header class="app-header">
        <div class="logo">
          <span class="logo-icon" aria-hidden="true">▣</span>
          <h1>Barcode Scanner</h1>
        </div>
        <span class="phase-badge">Phase ${CURRENT_PHASE}</span>
      </header>

      <main class="app-main">
        <section class="video-section">
          <div class="preview-grid">
            <div class="video-wrapper" id="live-wrapper">
              <video id="camera-preview" class="camera-video" playsinline webkit-playsinline muted autoplay></video>
              <canvas id="live-overlay" class="live-overlay"></canvas>
              <div id="barcode-toast" class="barcode-toast" hidden></div>
              <div id="video-placeholder" class="video-placeholder">
                <p>Camera preview</p>
                <p class="hint">Press Start Camera</p>
              </div>
              <span class="preview-label">Live</span>
            </div>
            <div class="video-wrapper process-wrapper">
              <canvas id="process-preview" class="process-canvas"></canvas>
              <div id="process-placeholder" class="video-placeholder">
                <p>Processed frame</p>
                <p class="hint">Enable processing loop</p>
              </div>
              <span class="preview-label">Processed</span>
            </div>
          </div>
          <div id="status-bar" class="status-bar" data-state="idle">
            <span id="state-label">idle</span>
          </div>
        </section>

        <section class="controls-card">
          <h3>Camera</h3>
          <div class="btn-row">
            <button id="btn-start" class="btn btn-primary" type="button">Start Camera</button>
            <button id="btn-stop" class="btn btn-secondary" type="button" disabled>Stop</button>
          </div>
          <div class="btn-row">
            <button id="btn-back" class="btn" type="button">Back Camera</button>
            <button id="btn-front" class="btn" type="button">Front Camera</button>
          </div>
          <div class="field">
            <label for="device-select">Select device</label>
            <select id="device-select" disabled>
              <option value="">— list devices after permission —</option>
            </select>
          </div>
        </section>

        <section class="controls-card">
          <h3>Frame Processing</h3>
          <div class="btn-row">
            <button id="btn-process-toggle" class="btn btn-primary" type="button" disabled>
              Start Processing Loop
            </button>
            <button id="btn-capture-once" class="btn" type="button" disabled>Capture Once</button>
          </div>
          <label class="filter-row" style="margin-bottom:0.75rem">
            <input type="checkbox" id="chk-decode" checked />
            <span>Enable barcode decode (single)</span>
          </label>
          <div class="field">
            <label for="max-width">Max process width</label>
            <select id="max-width">
              <option value="320">320</option>
              <option value="640" selected>640</option>
              <option value="960">960</option>
              <option value="1280">1280</option>
            </select>
          </div>
          <div id="filter-list" class="filter-list"></div>
          <div class="btn-row">
            <button id="btn-benchmark" class="btn btn-ghost" type="button" disabled>Run CPU Benchmark (30 frames)</button>
          </div>
        </section>

        <section class="info-card">
          <h3>Runtime Info</h3>
          <dl id="info-list" class="info-list">
            <div><dt>State</dt><dd id="info-state">idle</dd></div>
            <div><dt>Device</dt><dd id="info-device">—</dd></div>
            <div><dt>Resolution</dt><dd id="info-resolution">—</dd></div>
            <div><dt>Facing</dt><dd id="info-facing">—</dd></div>
            <div><dt>Process size</dt><dd id="info-proc-size">—</dd></div>
            <div><dt>Last process</dt><dd id="info-proc-ms">—</dd></div>
            <div><dt>Process FPS</dt><dd id="info-proc-fps">—</dd></div>
            <div><dt>OffscreenCanvas</dt><dd id="info-offscreen">—</dd></div>
          </dl>
        </section>

        <section class="info-card" id="benchmark-card" hidden>
          <h3>Benchmark Result</h3>
          <pre id="benchmark-out" class="error-box" style="color: var(--color-text)"></pre>
        </section>

        <section class="info-card" id="result-card" hidden>
          <h3>Last Barcode (Single)</h3>
          <dl class="info-list">
            <div><dt>Value</dt><dd id="result-value">—</dd></div>
            <div><dt>Format</dt><dd id="result-format">—</dd></div>
            <div><dt>Bounds</dt><dd id="result-bounds">—</dd></div>
          </dl>
        </section>

        <section class="info-card" id="error-card" hidden>
          <h3>Error</h3>
          <pre id="error-message" class="error-box"></pre>
        </section>

        <section class="info-card">
          <h3>Phase 2 Checklist</h3>
          <ul class="status-list">
            <li class="status-item done"><span class="status-icon">✓</span> Frame capture from video</li>
            <li class="status-item done"><span class="status-icon">✓</span> Canvas / OffscreenCanvas</li>
            <li class="status-item done"><span class="status-icon">✓</span> Modular preprocessors</li>
            <li class="status-item done"><span class="status-icon">✓</span> Grayscale / Contrast / Brightness</li>
            <li class="status-item done"><span class="status-icon">✓</span> Sharpen / Threshold / Denoise</li>
            <li class="status-item done"><span class="status-icon">✓</span> Resize / ROI crop</li>
            <li class="status-item done"><span class="status-icon">✓</span> CPU benchmark</li>
            <li class="status-item done"><span class="status-icon">✓</span> Single barcode decode (zxing-wasm)</li>
            <li class="status-item pending"><span class="status-icon">○</span> Rotation / geometry (Phase 4)</li>
          </ul>
        </section>
      </main>

      <footer class="app-footer">
        <p>Offline-first • Client-side only</p>
        <p class="version">${PROJECT_VERSION}</p>
      </footer>
    </div>
  `;

  const video = root.querySelector<HTMLVideoElement>('#camera-preview')!;
  const liveOverlay = root.querySelector<HTMLCanvasElement>('#live-overlay')!;
  const barcodeToast = root.querySelector<HTMLElement>('#barcode-toast')!;
  const liveWrapper = root.querySelector<HTMLElement>('#live-wrapper')!;
  const placeholder = root.querySelector<HTMLElement>('#video-placeholder')!;
  const processCanvas = root.querySelector<HTMLCanvasElement>('#process-preview')!;
  const processPlaceholder = root.querySelector<HTMLElement>('#process-placeholder')!;
  const stateLabel = root.querySelector<HTMLElement>('#state-label')!;
  const statusBar = root.querySelector<HTMLElement>('#status-bar')!;
  const btnStart = root.querySelector<HTMLButtonElement>('#btn-start')!;
  const btnStop = root.querySelector<HTMLButtonElement>('#btn-stop')!;
  const btnBack = root.querySelector<HTMLButtonElement>('#btn-back')!;
  const btnFront = root.querySelector<HTMLButtonElement>('#btn-front')!;
  const deviceSelect = root.querySelector<HTMLSelectElement>('#device-select')!;
  const btnProcessToggle = root.querySelector<HTMLButtonElement>('#btn-process-toggle')!;
  const btnCaptureOnce = root.querySelector<HTMLButtonElement>('#btn-capture-once')!;
  const btnBenchmark = root.querySelector<HTMLButtonElement>('#btn-benchmark')!;
  const maxWidthSelect = root.querySelector<HTMLSelectElement>('#max-width')!;
  const filterList = root.querySelector<HTMLElement>('#filter-list')!;
  const resultCard = root.querySelector<HTMLElement>('#result-card')!;
  const resultValue = root.querySelector('#result-value')!;
  const resultFormat = root.querySelector('#result-format')!;
  const resultBounds = root.querySelector('#result-bounds')!;
  const chkDecode = root.querySelector<HTMLInputElement>('#chk-decode')!;
  const errorCard = root.querySelector<HTMLElement>('#error-card')!;
  const errorMessage = root.querySelector<HTMLElement>('#error-message')!;
  const benchmarkCard = root.querySelector<HTMLElement>('#benchmark-card')!;
  const benchmarkOut = root.querySelector<HTMLElement>('#benchmark-out')!;

  const infoState = root.querySelector('#info-state')!;
  const infoDevice = root.querySelector('#info-device')!;
  const infoResolution = root.querySelector('#info-resolution')!;
  const infoFacing = root.querySelector('#info-facing')!;
  const infoProcSize = root.querySelector('#info-proc-size')!;
  const infoProcMs = root.querySelector('#info-proc-ms')!;
  const infoProcFps = root.querySelector('#info-proc-fps')!;
  const infoOffscreen = root.querySelector('#info-offscreen')!;

  infoOffscreen.textContent = capture.supportsOffscreen ? 'yes' : 'no (HTMLCanvas fallback)';

  const FILTER_LABELS: Record<string, string> = {
    grayscale: 'Grayscale',
    contrast: 'Contrast',
    brightness: 'Brightness',
    denoise: 'Denoise',
    sharpen: 'Sharpen',
    threshold: 'Threshold',
    resize: 'Resize (linked to max width)',
  };

  function renderFilters(): void {
    filterList.innerHTML = '';
    for (const step of pipeline.getConfigs()) {
      if (step.id === 'roi') continue;
      const row = document.createElement('label');
      row.className = 'filter-row';
      const cb = document.createElement('input');
      cb.type = 'checkbox';
      cb.checked = step.enabled;
      cb.dataset.id = step.id;
      cb.addEventListener('change', () => {
        pipeline.setEnabled(step.id as PreprocessorId, cb.checked);
      });
      const span = document.createElement('span');
      span.textContent = FILTER_LABELS[step.id] ?? step.id;
      row.appendChild(cb);
      row.appendChild(span);
      filterList.appendChild(row);
    }
  }
  renderFilters();

  function updateStateUI(state: CameraState): void {
    stateLabel.textContent = state;
    statusBar.dataset.state = state;
    infoState.textContent = state;

    const active = state === 'active';
    const busy = state === 'requesting';

    btnStart.disabled = active || busy;
    btnStop.disabled = !active && state !== 'error';
    btnBack.disabled = busy;
    btnFront.disabled = busy;
    deviceSelect.disabled = busy;
    btnProcessToggle.disabled = !active;
    btnCaptureOnce.disabled = !active;
    btnBenchmark.disabled = !active;

    const wrapper = video.closest('.video-wrapper');
    if (active) {
      placeholder.hidden = true;
      placeholder.style.display = 'none';
      video.style.display = 'block';
      video.style.visibility = 'visible';
      video.style.opacity = '1';
      wrapper?.classList.add('is-live');
    } else {
      video.style.opacity = '0';
      placeholder.hidden = false;
      placeholder.style.display = '';
      wrapper?.classList.remove('is-live');
      stopProcessLoop();
    }
  }

  function showError(err: CameraError): void {
    errorCard.hidden = false;
    errorMessage.textContent = `${err.code}\n${err.message}`;
  }

  function clearError(): void {
    errorCard.hidden = true;
    errorMessage.textContent = '';
  }

  function updateInfoFromTrack(): void {
    const settings = engine.getSettings();
    if (!settings) {
      infoDevice.textContent = '—';
      infoResolution.textContent = '—';
      infoFacing.textContent = '—';
      return;
    }
    infoDevice.textContent = settings.deviceId
      ? `${settings.deviceId.slice(0, 12)}…`
      : engine.activeDeviceId ?? '—';
    infoResolution.textContent =
      settings.width && settings.height ? `${settings.width} × ${settings.height}` : '—';
    infoFacing.textContent = (settings.facingMode as string) || '—';
  }

  async function populateDevices(): Promise<void> {
    try {
      const devices = await engine.listDevices();
      deviceSelect.innerHTML = '';
      if (devices.length === 0) {
        const opt = document.createElement('option');
        opt.value = '';
        opt.textContent = 'No cameras found';
        deviceSelect.appendChild(opt);
        return;
      }
      for (const d of devices) {
        const opt = document.createElement('option');
        opt.value = d.deviceId;
        const facing = d.facingMode ? ` [${d.facingMode}]` : '';
        opt.textContent = `${d.label}${facing}`;
        if (d.deviceId === engine.activeDeviceId) opt.selected = true;
        deviceSelect.appendChild(opt);
      }
      deviceSelect.disabled = false;
    } catch (e) {
      logger.warn('Could not list devices', e);
    }
  }

  async function attachStream(stream: MediaStream): Promise<void> {
    video.setAttribute('playsinline', 'true');
    video.setAttribute('webkit-playsinline', 'true');
    video.muted = true;
    video.playsInline = true;
    video.autoplay = true;
    video.srcObject = null;
    video.srcObject = stream;

    await new Promise<void>((resolve) => {
      if (video.readyState >= 1) {
        resolve();
        return;
      }
      const onMeta = () => {
        video.removeEventListener('loadedmetadata', onMeta);
        resolve();
      };
      video.addEventListener('loadedmetadata', onMeta);
      setTimeout(resolve, 1500);
    });

    try {
      await video.play();
    } catch (e) {
      logger.warn('video.play() failed', e);
      try {
        await new Promise((r) => setTimeout(r, 200));
        await video.play();
      } catch (e2) {
        logger.warn('video.play() retry failed', e2);
      }
    }

    placeholder.hidden = true;
    placeholder.style.display = 'none';
    video.style.display = 'block';
    video.style.opacity = '1';
    video.closest('.video-wrapper')?.classList.add('is-live');

    updateInfoFromTrack();
    await populateDevices();
  }

  function getMaxWidth(): number {
    return Number(maxWidthSelect.value) || 640;
  }

  function playBeep(): void {
    try {
      if (!audioCtx) {
        const AC = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
        audioCtx = new AC();
      }
      // Resume if suspended (autoplay policy)
      if (audioCtx.state === 'suspended') {
        void audioCtx.resume();
      }
      const duration = 0.12;
      const osc = audioCtx.createOscillator();
      const gain = audioCtx.createGain();
      osc.type = 'sine';
      osc.frequency.value = 880;
      gain.gain.value = 0.0001;
      osc.connect(gain);
      gain.connect(audioCtx.destination);
      const t = audioCtx.currentTime;
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(0.25, t + 0.02);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + duration);
      osc.start(t);
      osc.stop(t + duration + 0.02);
    } catch (e) {
      logger.warn('beep failed', e);
    }
  }

  function showBarcode(result: BarcodeResult): void {
    resultCard.hidden = false;
    resultValue.textContent = result.value;
    resultFormat.textContent = result.format;
    resultBounds.textContent = `${Math.round(result.bounds.x)},${Math.round(result.bounds.y)} ${Math.round(result.bounds.width)}×${Math.round(result.bounds.height)}`;

    // New detection: beep + 2s live highlight
    const isNew =
      !highlightResult ||
      highlightResult.value !== result.value ||
      performance.now() > highlightUntil;
    if (isNew) {
      playBeep();
    }
    highlightResult = result;
    highlightUntil = performance.now() + 2000;
    barcodeToast.hidden = false;
    barcodeToast.textContent = result.value;
    drawLiveOverlay();
  }

  /** Map processed-frame bounds → live video element pixel space (object-fit: cover). */
  function mapBoundsToLiveVideo(result: BarcodeResult): { x: number; y: number; w: number; h: number } | null {
    const vw = video.videoWidth;
    const vh = video.videoHeight;
    const pw = lastProcessSize.width;
    const ph = lastProcessSize.height;
    if (!vw || !vh || !pw || !ph) return null;

    // Capture used maxWidth scaling from full video (ROI not used in Phase 3 default)
    const scale = pw / vw;
    // Bounds are in processed buffer coordinates
    const x = result.bounds.x / scale;
    const y = result.bounds.y / scale;
    const w = result.bounds.width / scale;
    const h = result.bounds.height / scale;
    return { x, y, w, h };
  }

  function drawLiveOverlay(): void {
    const rect = liveWrapper.getBoundingClientRect();
    const cssW = Math.max(1, Math.round(rect.width));
    const cssH = Math.max(1, Math.round(rect.height));
    if (liveOverlay.width !== cssW) liveOverlay.width = cssW;
    if (liveOverlay.height !== cssH) liveOverlay.height = cssH;

    const ctx = liveOverlay.getContext('2d');
    if (!ctx) return;
    ctx.clearRect(0, 0, cssW, cssH);

    const now = performance.now();
    if (!highlightResult || now > highlightUntil) {
      barcodeToast.hidden = true;
      highlightResult = null;
      return;
    }

    const mapped = mapBoundsToLiveVideo(highlightResult);
    const vw = video.videoWidth || 1;
    const vh = video.videoHeight || 1;

    // object-fit: cover mapping from video pixels → canvas CSS pixels
    const videoAspect = vw / vh;
    const boxAspect = cssW / cssH;
    let drawW: number;
    let drawH: number;
    let offX: number;
    let offY: number;
    if (videoAspect > boxAspect) {
      drawH = cssH;
      drawW = cssH * videoAspect;
      offX = (cssW - drawW) / 2;
      offY = 0;
    } else {
      drawW = cssW;
      drawH = cssW / videoAspect;
      offX = 0;
      offY = (cssH - drawH) / 2;
    }

    const sx = drawW / vw;
    const sy = drawH / vh;

    let bx: number;
    let by: number;
    let bw: number;
    let bh: number;
    if (mapped) {
      bx = offX + mapped.x * sx;
      by = offY + mapped.y * sy;
      bw = mapped.w * sx;
      bh = mapped.h * sy;
    } else {
      // Fallback: center box
      bw = cssW * 0.5;
      bh = cssH * 0.25;
      bx = (cssW - bw) / 2;
      by = (cssH - bh) / 2;
    }

    // Pulsing frame
    const pulse = 0.5 + 0.5 * Math.sin(now / 120);
    ctx.strokeStyle = `rgba(56, 189, 248, ${0.7 + 0.3 * pulse})`;
    ctx.lineWidth = 3 + pulse;
    ctx.strokeRect(bx, by, bw, bh);

    // Corner accents
    const corner = Math.min(24, bw / 4, bh / 4);
    ctx.strokeStyle = '#4ade80';
    ctx.lineWidth = 4;
    ctx.beginPath();
    // TL
    ctx.moveTo(bx, by + corner);
    ctx.lineTo(bx, by);
    ctx.lineTo(bx + corner, by);
    // TR
    ctx.moveTo(bx + bw - corner, by);
    ctx.lineTo(bx + bw, by);
    ctx.lineTo(bx + bw, by + corner);
    // BL
    ctx.moveTo(bx, by + bh - corner);
    ctx.lineTo(bx, by + bh);
    ctx.lineTo(bx + corner, by + bh);
    // BR
    ctx.moveTo(bx + bw - corner, by + bh);
    ctx.lineTo(bx + bw, by + bh);
    ctx.lineTo(bx + bw, by + bh - corner);
    ctx.stroke();

    // Keep toast visible during highlight window
    barcodeToast.hidden = false;
    barcodeToast.textContent = highlightResult.value;
  }

  function processOneFrame(): void {
    if (engine.currentState !== 'active') return;
    if (!video.videoWidth) return;

    const maxW = getMaxWidth();
    pipeline.setOptions('resize', {
      width: maxW,
      height: Math.round((maxW * 3) / 4),
    });

    const t0 = performance.now();
    try {
      const frame = capture.captureFromVideo(video, { maxWidth: maxW });
      const capMs = performance.now() - t0;
      const { frame: out, metrics } = pipeline.run(frame);
      metrics.captureMs = capMs;
      metrics.totalMs = capMs + metrics.processMs;
      lastProcessSize = { width: out.width, height: out.height };

      capture.drawToCanvas(out, processCanvas);
      processPlaceholder.hidden = true;
      processPlaceholder.style.display = 'none';

      // Draw bounds on processed preview while highlight is active
      if (highlightResult && performance.now() <= highlightUntil && highlightResult.bounds.width > 0) {
        const ctx = processCanvas.getContext('2d');
        if (ctx) {
          ctx.strokeStyle = '#38bdf8';
          ctx.lineWidth = 3;
          ctx.strokeRect(
            highlightResult.bounds.x,
            highlightResult.bounds.y,
            highlightResult.bounds.width,
            highlightResult.bounds.height
          );
        }
      }

      // Always refresh live overlay (clears after 2s)
      drawLiveOverlay();

      infoProcSize.textContent = `${out.width} × ${out.height} (${out.format})`;
      infoProcMs.textContent = `${metrics.totalMs.toFixed(1)} ms (cap ${capMs.toFixed(1)} + proc ${metrics.processMs.toFixed(1)})`;

      const now = performance.now();
      fpsWindow.push(now);
      fpsWindow = fpsWindow.filter((t) => now - t < 1000);
      infoProcFps.textContent = String(fpsWindow.length);

      // Phase 3: single decode (skip frames while previous decode is in flight)
      if (chkDecode.checked && !decodeBusy) {
        decodeBusy = true;
        void decoder
          .decode(out, { maxNumberOfSymbols: 1, tryHarder: true })
          .then((hit) => {
            if (hit && hit.value) showBarcode(hit);
          })
          .catch((e) => logger.warn('decode error', e))
          .finally(() => {
            decodeBusy = false;
          });
      }
    } catch (e) {
      logger.warn('process frame failed', e);
    }
  }

  function startProcessLoop(): void {
    if (processLoopId != null) return;
    btnProcessToggle.textContent = 'Stop Processing Loop';
    const tick = () => {
      processOneFrame();
      processLoopId = requestAnimationFrame(tick);
    };
    processLoopId = requestAnimationFrame(tick);
  }

  function stopProcessLoop(): void {
    if (processLoopId != null) {
      cancelAnimationFrame(processLoopId);
      processLoopId = null;
    }
    btnProcessToggle.textContent = 'Start Processing Loop';
    fpsWindow = [];
    infoProcFps.textContent = '—';
  }

  engine.on('statechange', (s) => updateStateUI(s));
  engine.on('error', (err) => showError(err));
  engine.on('trackended', () => {
    video.srcObject = null;
    updateInfoFromTrack();
    stopProcessLoop();
  });

  btnStart.addEventListener('click', async () => {
    clearError();
    try {
      const stream = await engine.startBackCamera();
      await attachStream(stream);
    } catch {
      /* emitted */
    }
  });

  btnStop.addEventListener('click', async () => {
    clearError();
    stopProcessLoop();
    await engine.stop();
    video.srcObject = null;
    updateInfoFromTrack();
  });

  btnBack.addEventListener('click', async () => {
    clearError();
    try {
      const stream = await engine.startBackCamera();
      await attachStream(stream);
    } catch {
      /* */
    }
  });

  btnFront.addEventListener('click', async () => {
    clearError();
    try {
      const stream = await engine.startFrontCamera();
      await attachStream(stream);
    } catch {
      /* */
    }
  });

  deviceSelect.addEventListener('change', async () => {
    const id = deviceSelect.value;
    if (!id) return;
    clearError();
    try {
      const stream = await engine.switchDevice(id);
      await attachStream(stream);
    } catch {
      /* */
    }
  });

  btnProcessToggle.addEventListener('click', () => {
    if (processLoopId != null) stopProcessLoop();
    else startProcessLoop();
  });

  btnCaptureOnce.addEventListener('click', () => processOneFrame());

  btnBenchmark.addEventListener('click', async () => {
    if (engine.currentState !== 'active') return;
    btnBenchmark.disabled = true;
    btnBenchmark.textContent = 'Benchmarking…';
    try {
      const result: BenchmarkResult = await runPipelineBenchmark(
        video,
        pipeline,
        30,
        getMaxWidth()
      );
      benchmarkCard.hidden = false;
      benchmarkOut.textContent = [
        `runs: ${result.runs}`,
        `avg capture: ${result.avgCaptureMs.toFixed(2)} ms`,
        `avg process: ${result.avgProcessMs.toFixed(2)} ms`,
        `avg total:   ${result.avgTotalMs.toFixed(2)} ms`,
        `min total:   ${result.minTotalMs.toFixed(2)} ms`,
        `max total:   ${result.maxTotalMs.toFixed(2)} ms`,
        `OffscreenCanvas: ${result.offscreen}`,
        result.lastMetrics
          ? `last size: ${result.lastMetrics.width}x${result.lastMetrics.height} ${result.lastMetrics.format}`
          : '',
        result.lastMetrics
          ? `steps: ${result.lastMetrics.steps.map((s) => `${s.name}=${s.durationMs.toFixed(2)}ms`).join(', ')}`
          : '',
      ]
        .filter(Boolean)
        .join('\n');
      logger.info('Benchmark result', result);
    } catch (e) {
      showError({
        code: 'UnknownError',
        message: e instanceof Error ? e.message : String(e),
      });
    } finally {
      btnBenchmark.disabled = false;
      btnBenchmark.textContent = 'Run CPU Benchmark (30 frames)';
    }
  });

  updateStateUI('idle');

  const env = CameraEngine.getEnvironmentInfo();
  logger.info('Camera environment', env);
  if (!env.secureContext || !env.supported) {
    if (!env.secureContext) {
      showError({
        code: 'SecurityError',
        message:
          'Camera requires a secure context (HTTPS or localhost).\n' +
          `Current: ${env.protocol}//${env.hostname}`,
      });
    } else {
      showError({
        code: 'NotFoundError',
        message: 'getUserMedia is not available in this browser/context.',
      });
    }
  }

  // Warm up WASM decoder in background (does not block UI)
  void decoder.init().catch((e) => logger.warn('Decoder preload failed', e));

  logger.info(`UI ready — Phase ${CURRENT_PHASE}`);
}

